 WHERE ACTIVE_ITEM_NM = #{itemNm}
AND ITEM_CODE <> #{itemCode}

mapper.update:
UPDATE ASSET_ITEM
   SET ITEM_NM = #{vo.itemNm}
     , ITEM_TY = #{vo.itemTy}
     , CL_CODE = #{vo.clCode}
     , UNIT_CODE = #{vo.unitCode}
     , MIN_QTY = #{vo.minQty}
     , LAST_UPDUSR_ID = #{actorId}
     , LAST_UPDT_PNTTM = SYSDATE()
 WHERE ITEM_CODE = #{vo.itemCode}

UPDATE ASSET_ITEM
   SET USE_AT = #{useAt}
     , LAST_UPDUSR_ID = #{actorId}
     , LAST_UPDT_PNTTM = SYSDATE()
 WHERE ITEM_CODE = #{itemCode}
